-- Base des mots importants (hebreu / arameen / grec), tiree des livrets
-- de Mickael A. : Noms de Dieu, Vocabulaire du croyant, Grands concepts.
create table if not exists bible_words (
  slug text primary key,
  term text,
  translit text not null,
  lang text not null,
  gloss text not null,
  theme text not null,
  sense text not null,
  christ text,
  refs text[] not null default '{}',
  created_at timestamptz not null default now()
);
alter table bible_words enable row level security;
drop policy if exists bible_words_read on bible_words;
create policy bible_words_read on bible_words for select using (true);

on conflict (slug) do update set
  term=excluded.term, translit=excluded.translit, lang=excluded.lang, gloss=excluded.gloss,
  theme=excluded.theme, sense=excluded.sense, christ=excluded.christ, refs=excluded.refs;
